import re


ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789.,?"
_INDEX = {character: index for index, character in enumerate(ALPHABET)}


def pack_symbols(text):
    if not isinstance(text, str):
        raise TypeError("text must be a string")

    encoded_words = []
    for word in re.findall(r"\S+", text):
        tokens = []
        for character in word.upper():
            if character in _INDEX:
                tokens.append(f"{_INDEX[character]:02d}")
        if tokens:
            encoded_words.append("|".join(tokens))
    return "||".join(encoded_words)


def unpack_symbols(encoded):
    if not isinstance(encoded, str):
        raise TypeError("encoded must be a string")

    words = []
    for encoded_word in encoded.split("/"):
        characters = []
        for token in encoded_word.split("|"):
            if len(token) == 2 and token.isascii() and token.isdecimal():
                index = int(token)
                if index < len(ALPHABET):
                    characters.append(ALPHABET[index])
        if characters:
            words.append("".join(characters))
    return " ".join(words)

